/* ---------- state (saved to the signed-in account; browser storage only when there is no server) ---------- */
let state = { clients: [], diagnoses: [], invoices: [], selectedClientId: null };
let serverMode = false, saveTimer = null, member = null, opts = {}, current = "clients", undo = [], docOff = [];
function pushState() {
  return fetch("/api/crm/state", { method: "PUT", headers: { "Content-Type": "application/json" }, credentials: "same-origin", body: JSON.stringify({ state: state }) })
    .then(function (r) { return r.ok; }).catch(function () { return false; });
}
function flushState() { if (saveTimer) { clearTimeout(saveTimer); saveTimer = null; return pushState(); } return Promise.resolve(true); }
function refreshStats() { // keep the header stats in step with edits made on the page (snapshots, invoices...)
  if (current !== "clients" && current !== "diagnosis" && current !== "invoices") return;
  const el = document.querySelector("#crm-view .ws-stats"); if (!el) return;
  const t = document.createElement("div"); t.innerHTML = pageHead(current); const n = t.querySelector(".ws-stats"); if (n) el.replaceWith(n);
}
function saveState() {
  refreshStats();
  if (serverMode) { clearTimeout(saveTimer); saveTimer = setTimeout(function () { saveTimer = null; pushState(); }, 400); return; }
  try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) { /* no storage */ }
}
async function loadState() {
  let loaded = null;
  try {
    const r = await fetch("/api/crm/state", { credentials: "same-origin" });
    if (r.ok && r.headers.get("x-imi-api")) {
      const d = await r.json(); serverMode = true; loaded = d.state;
      if (!loaded) { let legacy = null; try { legacy = localStorage.getItem(KEY); } catch (e) { /* ignore */ }
        if (legacy) { try { loaded = JSON.parse(legacy); } catch (e) { /* ignore */ } state = loaded || state; pushState().then(function (ok) { if (ok) { try { localStorage.removeItem(KEY); } catch (e) { /* ignore */ } } }); } }
    }
  } catch (e) { /* offline preview */ }
  if (!serverMode) { try { const raw = localStorage.getItem(KEY); if (raw) loaded = JSON.parse(raw); } catch (e) { /* ignore */ } }
  if (loaded && typeof loaded === "object") state = loaded;
  state.clients = state.clients || []; state.diagnoses = state.diagnoses || []; state.invoices = state.invoices || [];
}
function uid() { return Math.random().toString(36).slice(2, 9); }
function fmtNGN(n) { return "\u20A6" + (Number(n) || 0).toLocaleString("en-NG", { maximumFractionDigits: 0 }); }
function client(id) { return state.clients.find(function (c) { return c.id === id; }); }
const esc = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); };
const today = function () { return new Date().toISOString().slice(0, 10); };
const fmtDate = function (d) { if (!d) return "\u2014"; const x = new Date(d); return isNaN(x) ? "\u2014" : x.toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" }); };

