  const key = function (e) { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") { e.preventDefault(); if (document.body.classList.contains("ws-in-crm")) si.focus(); } };
  const outside = function (e) { if (!e.target.closest("#wsBell,#wsUser,.ws-topmenu")) closeMenus(); };
